const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const stripHtml=s=>{const d=document.createElement('div');d.innerHTML=String(s||'');return d.textContent||d.innerText||''};
const countWords=s=>{const t=stripHtml(s).trim();return t?t.split(/\s+/).length:0};
const reminderOptions=v=>Array.from({length:30},(_,i)=>`<option value="${i+1}" ${Number(v||7)===i+1?'selected':''}>${i+1} hari sebelum</option>`).join('');
const templates={
 article:{label:'Artikel Jurnal',target:10000,sections:['Abstract','Keywords','Introduction','Literature Review','Methodology','Results and Discussion','Conclusion','Acknowledgement','References'],phases:[['Persediaan Kajian',['Tentukan topik','Research problem','Research gap','Research questions','Objectives','Target journal']],['Rangka Artikel',['Title','Abstract','Introduction','Literature Review','Methodology','Results and Discussion','Conclusion']],['Research & Sources',['Collect references','Review papers','Save DOI','Organize citations','Figures / tables']],['Menulis',['Abstract','Introduction','Literature Review','Methodology','Results and Discussion','Conclusion']],['Academic Editing',['Grammar','Academic tone','Argument flow','Citation check','Similarity check','Word count']],['Review',['Co-author review','Supervisor review','Peer feedback','Revision']],['Submission',['Journal formatting','Cover letter','Author details','References','Submission checklist','Submit','Revision tracking']]]},
 thesis:{label:'Tesis',target:70000,sections:['Abstract','Acknowledgement','Chapter 1: Introduction','Chapter 2: Literature Review','Chapter 3: Methodology','Chapter 4: Results / Findings','Chapter 5: Discussion','Chapter 6: Conclusion & Recommendations','References','Appendices'],phases:[['Persediaan',['Tentukan topik','Research problem','Research gap','Research questions','Objectives','Scope','Supervisor discussion']],['Rangka Tesis',['Abstract','Introduction','Literature Review','Methodology','Results / Findings','Discussion','Conclusion & Recommendations']],['Research & Data',['Ethics approval jika perlu','Data collection','Reference management','Figures / tables','Data analysis plan']],['Menulis',['Chapter 1','Chapter 2','Chapter 3','Chapter 4','Chapter 5','Chapter 6']],['Suntingan Akademik',['Academic tone','Argument flow','Citation check','Formatting','Tables / figures','Word count']],['Semakan Penyelia',['Submit chapters','Receive feedback','Revision','Supervisor approval']],['Akhir & Submission',['Final proofreading','University formatting','Declaration / front matter','References','Appendices','Final thesis submission']]]},
 book:{label:'Buku',target:50000,sections:['Pengenalan','Bab 1','Bab 2','Bab 3','Penutup'],phases:[['Persediaan',['Tentukan tujuan buku','Pembaca sasaran','Genre','Gaya penulisan','Target words','Deadline']],['Rangka Buku',['Tajuk','Bahagian','Bab','Subbab','Susun flow buku']],['Jadual',['Tarikh mula','Tarikh siap','Daily writing goal','Weekly writing target','Jadual bab']],['Menulis',['Tulis bab demi bab','Semak target words','Lengkapkan manuskrip']],['Suntingan',['Self edit','Grammar','Structure','Consistency','Fact checking']],['Maklum Balas',['Beta reader','Editor','Peer review','Feedback','Revision']],['Akhir',['Final proofread','Formatting','Cover','ISBN','Export','Publish']]]},
 ebook:{label:'eBook',target:15000,sections:['Pengenalan','Bab 1','Bab 2','Bab 3','Checklist / Bonus','Penutup','CTA'],phases:[['Idea & Audience',['Tentukan masalah pembaca','Persona pembaca','Outcome eBook']],['Outline',['Tajuk','Bab','Subbab','Flow']],['Content Plan',['Research','Contoh','Visual','Jadual penulisan']],['Writing',['Draft setiap bab','Lengkapkan CTA','Semak target']],['Editing',['Bahasa','Flow','Kejelasan','Fact check']],['Design & Review',['Layout','Cover','Visual','Proofread','Feedback']],['Publishing',['Final PDF','EPUB','Landing copy','Publish']]]}
};
let state={session:null,profile:null,projects:[],current:null,currentTab:'overview',activeSection:null,focus:false,toolsHidden:false};
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.className='toast show'+(bad?' bad':'');clearTimeout(t._x);t._x=setTimeout(()=>t.className='toast',2600)}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden');$('#modalContent').innerHTML=''}
window.closeModal=closeModal;
async function authCall(payload,admin=false){const headers={'Content-Type':'application/json','apikey':SUPABASE_KEY};if(admin){const s=(await sb.auth.getSession()).data.session;if(s)headers.Authorization='Bearer '+s.access_token}const r=await fetch(AUTH_URL,{method:'POST',headers,body:JSON.stringify(payload)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Ralat');return j}
async function setSession(a,r){const {data,error}=await sb.auth.setSession({access_token:a,refresh_token:r});if(error)throw error;state.session=data.session;await loadProfile()}
async function loadProfile(){const u=(await sb.auth.getUser()).data.user;if(!u)return null;const {data,error}=await sb.from('nv1_profiles').select('*').eq('id',u.id).single();if(error)throw error;state.profile=data;return data}
async function loadProjects(){const {data,error}=await sb.from('nv1_projects').select('*').order('updated_at',{ascending:false});if(error)throw error;state.projects=data||[]}
function showPublic(panel='login'){$('#public').classList.remove('hidden');$('#app').classList.add('hidden');$$('.auth-panel').forEach(x=>x.classList.add('hidden'));$('#'+panel+'Panel').classList.remove('hidden')}
async function enterApp(){await loadProjects();$('#public').classList.add('hidden');$('#app').classList.remove('hidden');$('#adminNav').classList.toggle('hidden',state.profile?.role!=='admin');renderDashboard()}
function nav(name){$$('.sidebar [data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===name));if(innerWidth<=820)toggleNav(false)}
function toggleNav(force){const app=$('#app'),on=force??!app.classList.contains('nav-open');app.classList.toggle('nav-open',on)}
function projectWords(p){return Object.values(p?.content||{}).reduce((n,v)=>n+countWords(v),0)}
function projectPct(p){return Math.min(100,Math.round(projectWords(p)/Math.max(1,Number(p.target_words||1))*100))}
function projectCard(p){const w=projectWords(p),pct=projectPct(p);return `<button class="project-card" data-open="${p.id}"><span class="type-pill">${esc(templates[p.project_type]?.label||p.project_type)}</span><h3>${esc(p.title)}</h3><div class="progress"><i style="width:${pct}%"></i></div><div class="muted">${w.toLocaleString()} / ${Number(p.target_words||0).toLocaleString()} perkataan · ${pct}%</div>${p.deadline?`<div class="muted" style="margin-top:8px">Deadline: ${esc(p.deadline)}</div>`:''}</button>`}
function renderDashboard(){nav('dashboard');state.current=null;const words=state.projects.reduce((n,p)=>n+projectWords(p),0),active=state.projects.filter(p=>p.status!=='complete').length,done=state.projects.length-active;$('#main').innerHTML=`<div class="page-head"><div><h1>Dashboard</h1><p>Selamat datang, ${esc(state.profile?.display_name||state.profile?.username||'Penulis')}.</p></div><button class="btn primary" id="newProject">+ Projek Baharu</button></div><div class="stats"><div class="stat"><b>${state.projects.length}</b><span>Jumlah Projek</span></div><div class="stat words"><b>${words.toLocaleString()}</b><span>Jumlah Perkataan</span></div><div class="stat progress-card"><b>${done}</b><span>Projek Selesai</span></div><div class="stat sections"><b>${active}</b><span>Projek Aktif</span></div></div>${reminderCentre()}<div class="card"><div class="card-head"><h2>Projek Terkini</h2></div><div class="project-grid">${state.projects.length?state.projects.map(projectCard).join(''):'<div class="muted">Belum ada projek.</div>'}</div></div>`;$('#newProject').onclick=openCreate;$$('[data-open]').forEach(x=>x.onclick=()=>openProject(x.dataset.open))}
function reminderCentre(){const now=new Date(),rows=[];state.projects.forEach(p=>{if(p.deadline){const d=new Date(p.deadline+'T23:59:59'),days=Math.ceil((d-now)/86400000);if(days>=0&&days<=30)rows.push({title:p.title,label:'Project deadline',days,date:p.deadline})}const sd=p.goals?.section_deadlines||{};Object.entries(sd).forEach(([s,v])=>{if(v?.due_date){const d=new Date(v.due_date+'T23:59:59'),days=Math.ceil((d-now)/86400000);if(days>=0&&days<=Number(v.reminder_days||7))rows.push({title:p.title,label:s,days,date:v.due_date})}})});if(!rows.length)return '';rows.sort((a,b)=>a.days-b.days);return `<div class="card"><div class="card-head"><h2>Reminder Deadline</h2><span class="type-pill">${rows.length} upcoming</span></div>${rows.slice(0,8).map(r=>`<div class="health"><span><b>${esc(r.title)}</b><br><small class="muted">${esc(r.label)}</small></span><b>${r.days===0?'Hari ini':r.days+' hari'}</b><em>${esc(r.date)}</em></div>`).join('')}</div>`}
function renderProjects(){nav('projects');$('#main').innerHTML=`<div class="page-head"><div><h1>My Projects</h1><p>Semua manuskrip anda.</p></div><button class="btn primary" id="newProject">+ Projek Baharu</button></div><div class="project-grid">${state.projects.map(projectCard).join('')||'<div class="muted">Belum ada projek.</div>'}</div>`;$('#newProject').onclick=openCreate;$$('[data-open]').forEach(x=>x.onclick=()=>openProject(x.dataset.open))}
function openCreate(){modal(`<h2>Projek Baharu</h2><label>Tajuk<input id="cpTitle" placeholder="Tajuk penulisan"></label><label>Jenis<select id="cpType">${Object.entries(templates).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><label>Target perkataan<input id="cpTarget" type="number" value="10000"></label><label>Deadline projek<input id="cpDeadline" type="date"></label><label>Bahasa<select id="cpLang"><option>Malay</option><option>English</option></select></label><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="cpSave">Cipta Projek</button></div>`);$('#cpType').onchange=e=>$('#cpTarget').value=templates[e.target.value].target;$('#cpSave').onclick=createProject}
async function createProject(){const type=$('#cpType').value,title=$('#cpTitle').value.trim();if(!title)return toast('Masukkan tajuk.',true);const t=templates[type],target=Number($('#cpTarget').value||t.target),content=Object.fromEntries(t.sections.map(s=>[s,''])),outline=t.sections.filter(s=>!['Keywords','References'].includes(s)).map((s,i)=>({id:crypto.randomUUID(),title:s,notes:'',target_words:Math.round(target/Math.max(1,t.sections.length)),status:'not_started',children:[],order:i})),checklist=t.phases.map(([name,items],i)=>({id:crypto.randomUUID(),name,order:i,items:items.map(x=>({id:crypto.randomUUID(),text:x,done:false}))})),goals={daily:500,weekly:3000,section_deadlines:Object.fromEntries(t.sections.map(s=>[s,{due_date:'',reminder_days:7,target_words:0}])),notes:[],references:[],versions:[],submission:{},journal:{},revisions:[]};const u=(await sb.auth.getUser()).data.user;const {data,error}=await sb.from('nv1_projects').insert({user_id:u.id,title,project_type:type,target_words:target,deadline:$('#cpDeadline').value||null,language:$('#cpLang').value,status:'draft',content,outline,checklist,goals}).select().single();if(error)return toast(error.message,true);closeModal();state.projects.unshift(data);openProject(data.id)}
function normalizeProject(p){const t=templates[p.project_type];if(!t)return;p.content=p.content||{};const next={};t.sections.forEach(s=>next[s]=p.content[s]??'');Object.keys(p.content).forEach(s=>{if(!(s in next))next[s]=p.content[s]});p.content=next;p.goals=p.goals||{};p.goals.section_deadlines=p.goals.section_deadlines||{};Object.keys(p.content).forEach(s=>p.goals.section_deadlines[s]=p.goals.section_deadlines[s]||{due_date:'',reminder_days:7,target_words:0});p.goals.notes=p.goals.notes||[];p.goals.references=p.goals.references||[];p.goals.versions=p.goals.versions||[];p.goals.submission=p.goals.submission||{};p.goals.journal=p.goals.journal||{};p.goals.revisions=p.goals.revisions||[]}
function openProject(id){state.current=state.projects.find(p=>String(p.id)===String(id));if(!state.current)return;normalizeProject(state.current);renderProject('overview')}
const tabDefs=[['overview','Overview'],['writing','Zon Menulis'],['outline','Pengurus Rangka'],['checklist','Senarai Semak'],['notes','Research Notes'],['references','References'],['versions','Versions'],['export','Export']];
function tabs(active){return `<div class="tabs">${tabDefs.map(([k,l])=>`<button data-tab="${k}" class="${active===k?'active':''}">${l}</button>`).join('')}</div>`}
function renderProject(tab){state.currentTab=tab;nav('projects');const p=state.current,w=projectWords(p),pct=projectPct(p);let body=tab==='overview'?overviewView(p):tab==='writing'?writingView(p):tab==='outline'?outlineView(p):tab==='checklist'?checklistView(p):tab==='notes'?notesView(p):tab==='references'?referencesView(p):tab==='versions'?versionsView(p):exportView(p);$('#main').innerHTML=`<div class="page-head"><div><button class="link" id="backProjects">← Semua Projek</button><h1>${esc(p.title)}</h1><p>${esc(templates[p.project_type]?.label)} · ${w.toLocaleString()} / ${Number(p.target_words||0).toLocaleString()} perkataan</p></div><span class="type-pill">${pct}%</span></div>${tabs(tab)}${body}`;$('#backProjects').onclick=renderProjects;$$('[data-tab]').forEach(x=>x.onclick=()=>renderProject(x.dataset.tab));bindTab(tab)}
function overviewView(p){const w=projectWords(p),pct=projectPct(p);return `<div class="stats"><div class="stat words"><b>${w.toLocaleString()}</b><span>Jumlah Perkataan</span></div><div class="stat progress-card"><b>${pct}%</b><span>% Kemajuan</span></div><div class="stat sections"><b>${Object.keys(p.content).length}</b><span>Jumlah Bahagian</span></div><div class="stat deadline"><b>${esc(p.deadline||'—')}</b><span>Tarikh Deadline</span></div></div><div class="grid2"><div class="card"><h2>Writing Health</h2>${Object.entries(p.content).filter(([k])=>!['Keywords','References'].includes(k)).map(([k,v])=>{const n=countWords(v),s=n===0?'Belum mula':n<100?'Draft awal':'Sedang ditulis';return `<div class="health"><span>${esc(k)}</span><b>${n} words</b><em>${s}</em></div>`}).join('')}</div><div class="card"><h2>Writing Goals</h2><label>Target Harian<input id="goalDaily" type="number" value="${Number(p.goals.daily||500)}"></label><label>Target Mingguan<input id="goalWeekly" type="number" value="${Number(p.goals.weekly||3000)}"></label><label>Project Deadline<input id="projectDeadline" type="date" value="${esc(p.deadline||'')}"></label><button class="btn primary" id="saveGoals" style="margin-top:14px">Simpan Goal</button></div></div>${deadlinesView(p)}${specialSubmissionView(p)}`}
function deadlinesView(p){return `<div class="card"><div class="card-head"><div><h2>${p.project_type==='thesis'?'Thesis Chapter Deadlines':'Section Deadlines'}</h2><p class="muted">Due date, reminder 1–30 hari dan target perkataan setiap bahagian.</p></div></div><div class="deadline-table">${Object.keys(p.content).map((s,i)=>{const d=p.goals.section_deadlines[s]||{};return `<div class="deadline-row" data-dsec="${esc(s)}"><div class="deadline-section"><i>${i+1}</i><b>${esc(s)}</b></div><label>Due Date<input class="d-date" type="date" value="${esc(d.due_date||'')}"></label><label>Reminder<select class="d-rem">${reminderOptions(d.reminder_days)}</select></label><label>Word Target<input class="d-target" type="number" min="0" value="${Number(d.target_words||0)}"></label></div>`}).join('')}</div><div class="actions"><button class="btn primary" id="saveDeadlines">Simpan Deadlines</button></div></div>`}
function specialSubmissionView(p){const s=p.goals.submission||{},j=p.goals.journal||{};if(p.project_type==='article')return `<div class="card"><h2>Article Submission & Tracking</h2><div class="submission-grid"><div><h3>Submission kepada Supervisor</h3><label>Tarikh<input id="supDate" type="date" value="${esc(s.supervisor_date||'')}"></label><label>Reminder<select id="supRem">${reminderOptions(s.supervisor_reminder)}</select></label><label>Tarikh Feedback<input id="supFeedback" type="date" value="${esc(s.feedback_date||'')}"></label><label>Status Supervisor<select id="supStatus"><option>Belum dihantar</option><option>Submitted</option><option>Feedback Received</option><option>Revision Required</option><option>Approved</option></select></label></div><div><h3>Journal Profile</h3><label>Journal Name<input id="journalName" value="${esc(j.name||'')}"></label><label>Publisher / URL<input id="journalPublisher" value="${esc(j.publisher||'')}"></label><label>Submission Date<input id="journalDate" type="date" value="${esc(j.submission_date||'')}"></label><label>Reminder<select id="journalRem">${reminderOptions(j.reminder_days)}</select></label><label>Status Artikel<select id="articleStatus"><option>Draft</option><option>Supervisor Review</option><option>Ready for Submission</option><option>Submitted</option><option>Under Review</option><option>Minor Revision</option><option>Major Revision</option><option>Accepted</option><option>Published</option><option>Rejected</option></select></label></div></div><h3 style="margin-top:22px">Revision Tracker</h3><div id="revisionList">${p.goals.revisions.map((r,i)=>`<div class="health"><span><b>${esc(r.title||'Revision')}</b><br><small class="muted">${esc(r.notes||'')}</small></span><b>${esc(r.status||'Open')}</b><button class="btn small danger" data-delrev="${i}">Delete</button></div>`).join('')||'<p class="muted">Belum ada revision.</p>'}</div><div class="actions"><button class="btn" id="addRevision">+ Add Revision</button><button class="btn primary" id="saveSubmission">Simpan Tracking</button></div></div>`;if(p.project_type==='thesis')return `<div class="card"><h2>Thesis Submission Tracking</h2><div class="submission-grid"><div><h3>Submission kepada Supervisor</h3><label>Tarikh<input id="supDate" type="date" value="${esc(s.supervisor_date||'')}"></label><label>Reminder<select id="supRem">${reminderOptions(s.supervisor_reminder)}</select></label><label>Status<select id="supStatus"><option>Belum dihantar</option><option>Submitted</option><option>Feedback Received</option><option>Revision Required</option><option>Approved</option></select></label></div><div><h3>Final Thesis Submission</h3><label>Tarikh<input id="finalDate" type="date" value="${esc(s.final_date||'')}"></label><label>Reminder<select id="finalRem">${reminderOptions(s.final_reminder)}</select></label><label>Status<select id="finalStatus"><option>Draft</option><option>Supervisor Review</option><option>Ready for Submission</option><option>Submitted</option><option>Corrections Required</option><option>Completed</option></select></label></div></div><div class="actions"><button class="btn primary" id="saveSubmission">Simpan Submission Tracking</button></div></div>`;return ''}
function writingView(p){const secs=Object.keys(p.content),sec=state.activeSection&&secs.includes(state.activeSection)?state.activeSection:secs[0];state.activeSection=sec;return `<div id="writerLayout" class="writer-layout ${state.focus?'focus-mode':''} ${state.toolsHidden?'tools-hidden':''}"><aside class="section-list">${secs.map(s=>`<button data-section="${esc(s)}" class="${s===sec?'active':''}">${esc(s)}<small>${countWords(p.content[s])} words</small></button>`).join('')}</aside><section class="editor-card"><div class="editor-head"><div><h2 id="sectionTitle">${esc(sec)}</h2><small id="saveState">Autosave aktif</small></div><div class="editor-actions"><button class="btn small" id="undoBtn">↶ Undo</button><button class="btn small" id="redoBtn">↷ Redo</button><button class="btn small" id="toolsToggle">${state.toolsHidden?'Show Tools':'Hide Tools'}</button><button class="btn small" id="focusToggle">${state.focus?'Exit Focus':'Focus Writing'}</button><button class="btn primary small" id="manualSave">💾 SIMPAN / SAVE</button></div></div><div class="format-toolbar"><select id="fontFamily"><option>Times New Roman</option><option>Arial</option><option>Calibri</option><option>Georgia</option><option>Garamond</option></select><select id="fontSize"><option value="2">10</option><option value="3" selected>12</option><option value="4">14</option><option value="5">18</option></select><select id="lineHeight"><option value="1.0">1.0</option><option value="1.15">1.15</option><option value="1.5" selected>1.5</option><option value="2">2.0</option></select><button data-cmd="bold"><b>B</b></button><button data-cmd="italic"><i>I</i></button><button data-cmd="underline"><u>U</u></button><button data-cmd="justifyLeft">Left</button><button data-cmd="justifyCenter">Center</button><button data-cmd="justifyRight">Right</button><button data-cmd="justifyFull">Justify</button><button id="insertTable">▦ Table</button><button id="insertImage">🖼 Image</button><input id="imageFile" class="hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></div><div id="editor" class="rich-editor" contenteditable="true" spellcheck="true" data-placeholder="Mula menulis di sini...">${p.content[sec]||''}</div></section><aside class="writer-stats"><h3>Statistik</h3><div class="metric"><b id="sectionWords">${countWords(p.content[sec])}</b><span>Section words</span></div><div class="metric"><b id="totalWords">${projectWords(p)}</b><span>Total words</span></div><div class="metric"><b id="readingTime">${Math.max(1,Math.ceil(projectWords(p)/220))} min</b><span>Reading time</span></div></aside></div>`}
function outlineView(p){return `<div class="card"><div class="card-head"><h2>Pengurus Rangka</h2><button class="btn primary" id="addOutline">+ Tambah Bab / Bahagian</button></div>${(p.outline||[]).map((o,i)=>`<div class="outline-row" data-oi="${i}"><div>☰</div><div><input class="ol-title" value="${esc(o.title)}"><textarea class="ol-notes" placeholder="Nota rangka...">${esc(o.notes||'')}</textarea></div><div><input class="ol-target" type="number" value="${Number(o.target_words||0)}"><select class="ol-status"><option value="not_started">Not Started</option><option value="drafting">Drafting</option><option value="review">Review</option><option value="complete">Complete</option></select><button class="btn small danger del-outline" style="margin-top:8px">Delete</button></div></div>`).join('')}</div>`}
function checklistView(p){const items=(p.checklist||[]).flatMap(x=>x.items),done=items.filter(x=>x.done).length,pct=Math.round(done/Math.max(1,items.length)*100);return `<div class="card"><div class="card-head"><div><h2>Senarai Semak Fasa</h2><p class="muted">${done}/${items.length} selesai · ${pct}%</p></div><div class="progress" style="width:220px"><i style="width:${pct}%"></i></div></div><div class="phases">${(p.checklist||[]).map((ph,pi)=>`<section class="phase"><h3>Fasa ${pi+1}: ${esc(ph.name)}</h3>${ph.items.map((it,ii)=>`<label class="check"><input type="checkbox" data-check="${pi}:${ii}" ${it.done?'checked':''}><span>${esc(it.text)}</span></label>`).join('')}<button class="link add-check" data-pi="${pi}">+ Tambah item</button></section>`).join('')}</div></div>`}
function notesView(p){return `<div class="card"><div class="card-head"><div><h2>Research Notes</h2><p class="muted">Simpan tajuk note dan kandungan yang berkaitan dengan projek.</p></div><button class="btn primary" id="addNote">+ Tambah Note</button></div><div id="notesList">${p.goals.notes.map((n,i)=>`<div class="note-card" data-ni="${i}"><input class="note-title" placeholder="Tajuk" value="${esc(n.title||'')}"><textarea class="note-body" rows="5" placeholder="Notes...">${esc(n.body||'')}</textarea><div class="actions"><button class="btn small danger del-note">Delete</button><button class="btn small primary save-note">Save</button></div></div>`).join('')||'<p class="muted">Belum ada research note.</p>'}</div></div>`}
function referencesView(p){return `<div class="card"><div class="card-head"><div><h2>References</h2><p class="muted">Simpan rujukan dan format citation untuk digunakan semula dalam manuskrip.</p></div><button class="btn primary" id="addRef">+ Tambah Reference</button></div>${p.goals.references.map((r,i)=>`<div class="reference-card" data-ri="${i}"><div class="reference-meta"><input class="ref-title" placeholder="Tajuk / Author" value="${esc(r.title||'')}"><select class="ref-style"><option>APA 7</option><option>Harvard</option><option>MLA</option><option>Chicago</option><option>IEEE</option></select></div><textarea class="ref-text" rows="4" placeholder="Formatted reference / DOI / URL">${esc(r.text||'')}</textarea><div class="actions"><button class="btn small" data-copyref="${i}">Copy Citation</button><button class="btn small danger del-ref">Delete</button><button class="btn small primary save-ref">Save</button></div></div>`).join('')||'<p class="muted">Belum ada reference.</p>'}</div>`}
function versionsView(p){const arr=p.goals.versions||[];return `<div class="card"><div class="card-head"><div><h2>Versions</h2><p class="muted">Simpan manuskrip secara manual dan buka semula bila diperlukan.</p></div><button class="btn primary" id="saveVersion">Simpan Manuskrip</button></div>${arr.length?arr.slice().reverse().map((v,ri)=>{const i=arr.length-1-ri;return `<div class="version-row"><div><b>${esc(v.name)}</b><div class="muted">${new Date(v.at).toLocaleString('ms-MY')}</div></div><div class="actions"><button class="btn small" data-openver="${i}">Buka</button><button class="btn small danger" data-delver="${i}">Delete</button></div></div>`}).join(''):'<p class="muted">Belum ada manuskrip disimpan.</p>'}</div>`}
function exportView(p){return `<div class="grid2"><div class="card"><h2>Export Manuskrip</h2><p class="muted">Gabungkan semua bahagian manuskrip mengikut struktur projek.</p><div class="actions" style="justify-content:flex-start"><button class="btn primary" id="exportDocx">Download Word / DOCX</button><button class="btn" id="exportTxt">TXT</button><button class="btn" id="printPdf">Print / Save PDF</button><button class="btn" id="shareCloud">Share / Save to Cloud</button></div></div><div class="card"><h2>Ringkasan</h2><div class="profile-row"><span>Jumlah perkataan</span><b>${projectWords(p).toLocaleString()}</b></div><div class="profile-row"><span>Jumlah bahagian</span><b>${Object.keys(p.content).length}</b></div><div class="profile-row"><span>Project</span><b>${esc(templates[p.project_type]?.label)}</b></div></div></div>`}
async function saveProject(){const p=state.current;p.updated_at=new Date().toISOString();const {error}=await sb.from('nv1_projects').update({title:p.title,target_words:p.target_words,deadline:p.deadline,status:p.status,content:p.content,outline:p.outline,checklist:p.checklist,goals:p.goals,updated_at:p.updated_at}).eq('id',p.id);if(error)throw error;const idx=state.projects.findIndex(x=>x.id===p.id);if(idx>=0)state.projects[idx]=p}
function bindTab(tab){const p=state.current;if(tab==='overview'){const s=p.goals.submission||{},j=p.goals.journal||{};if($('#supStatus'))$('#supStatus').value=s.supervisor_status||'Belum dihantar';if($('#finalStatus'))$('#finalStatus').value=s.final_status||'Draft';if($('#articleStatus'))$('#articleStatus').value=j.status||'Draft';$('#saveGoals').onclick=async()=>{p.goals.daily=Number($('#goalDaily').value||0);p.goals.weekly=Number($('#goalWeekly').value||0);p.deadline=$('#projectDeadline').value||null;try{await saveProject();toast('Writing goal disimpan.')}catch(e){toast(e.message,true)}};$('#saveDeadlines').onclick=async()=>{$$('[data-dsec]').forEach(r=>p.goals.section_deadlines[r.dataset.dsec]={due_date:r.querySelector('.d-date').value,reminder_days:Number(r.querySelector('.d-rem').value),target_words:Number(r.querySelector('.d-target').value||0)});try{await saveProject();toast('Deadlines disimpan.')}catch(e){toast(e.message,true)}};if($('#saveSubmission'))$('#saveSubmission').onclick=async()=>{p.goals.submission={...p.goals.submission,supervisor_date:$('#supDate')?.value||'',supervisor_reminder:Number($('#supRem')?.value||7),supervisor_status:$('#supStatus')?.value||'',feedback_date:$('#supFeedback')?.value||'',final_date:$('#finalDate')?.value||'',final_reminder:Number($('#finalRem')?.value||7),final_status:$('#finalStatus')?.value||''};if(p.project_type==='article')p.goals.journal={name:$('#journalName').value.trim(),publisher:$('#journalPublisher').value.trim(),submission_date:$('#journalDate').value,reminder_days:Number($('#journalRem').value||7),status:$('#articleStatus').value};try{await saveProject();toast('Submission tracking disimpan.')}catch(e){toast(e.message,true)}};if($('#addRevision'))$('#addRevision').onclick=()=>{modal(`<h2>Add Revision</h2><label>Tajuk<input id="revTitle"></label><label>Notes<textarea id="revNotes" rows="4"></textarea></label><label>Status<select id="revStatus"><option>Open</option><option>In Progress</option><option>Completed</option></select></label><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="saveRev">Add</button></div>`);$('#saveRev').onclick=async()=>{p.goals.revisions.push({title:$('#revTitle').value.trim()||'Revision',notes:$('#revNotes').value.trim(),status:$('#revStatus').value,at:new Date().toISOString()});await saveProject();closeModal();renderProject('overview')}};$$('[data-delrev]').forEach(b=>b.onclick=async()=>{p.goals.revisions.splice(Number(b.dataset.delrev),1);await saveProject();renderProject('overview')})}
if(tab==='writing')bindWriter(p);if(tab==='outline'){$('#addOutline').onclick=async()=>{p.outline=p.outline||[];p.outline.push({id:crypto.randomUUID(),title:'Bab / Bahagian Baharu',notes:'',target_words:1000,status:'not_started',children:[],order:p.outline.length});await saveProject();renderProject('outline')};$$('.outline-row').forEach(r=>{const i=Number(r.dataset.oi),o=p.outline[i];r.querySelector('.ol-status').value=o.status||'not_started';r.querySelector('.ol-title').onchange=async e=>{o.title=e.target.value;await saveProject()};r.querySelector('.ol-notes').onchange=async e=>{o.notes=e.target.value;await saveProject()};r.querySelector('.ol-target').onchange=async e=>{o.target_words=Number(e.target.value||0);await saveProject()};r.querySelector('.ol-status').onchange=async e=>{o.status=e.target.value;await saveProject()};r.querySelector('.del-outline').onclick=async()=>{p.outline.splice(i,1);await saveProject();renderProject('outline')}})}
if(tab==='checklist'){$$('[data-check]').forEach(c=>c.onchange=async()=>{const [pi,ii]=c.dataset.check.split(':').map(Number);p.checklist[pi].items[ii].done=c.checked;await saveProject();renderProject('checklist')});$$('.add-check').forEach(b=>b.onclick=()=>{const text=prompt('Item checklist baharu');if(text){p.checklist[Number(b.dataset.pi)].items.push({id:crypto.randomUUID(),text,done:false});saveProject().then(()=>renderProject('checklist'))}})}
if(tab==='notes'){$('#addNote').onclick=()=>{p.goals.notes.push({title:'',body:''});renderProject('notes')};$$('.note-card').forEach(c=>{const i=Number(c.dataset.ni);c.querySelector('.save-note').onclick=async()=>{p.goals.notes[i]={title:c.querySelector('.note-title').value.trim(),body:c.querySelector('.note-body').value};await saveProject();toast('Research note disimpan.')};c.querySelector('.del-note').onclick=async()=>{p.goals.notes.splice(i,1);await saveProject();renderProject('notes')}})}
if(tab==='references'){$('#addRef').onclick=()=>{p.goals.references.push({title:'',style:'APA 7',text:''});renderProject('references')};$$('.reference-card').forEach(c=>{const i=Number(c.dataset.ri),r=p.goals.references[i];c.querySelector('.ref-style').value=r.style||'APA 7';c.querySelector('.save-ref').onclick=async()=>{p.goals.references[i]={title:c.querySelector('.ref-title').value.trim(),style:c.querySelector('.ref-style').value,text:c.querySelector('.ref-text').value};await saveProject();toast('Reference disimpan.')};c.querySelector('.del-ref').onclick=async()=>{p.goals.references.splice(i,1);await saveProject();renderProject('references')}});$$('[data-copyref]').forEach(b=>b.onclick=async()=>{const r=p.goals.references[Number(b.dataset.copyref)];await navigator.clipboard.writeText(r.text||r.title||'');toast('Citation disalin.')})}
if(tab==='versions'){$('#saveVersion').onclick=()=>{modal(`<h2>Simpan Manuskrip</h2><label>Nama versi<input id="verName" value="Manuskrip ${p.goals.versions.length+1}"></label><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="confirmVersion">Simpan</button></div>`);$('#confirmVersion').onclick=async()=>{p.goals.versions.push({name:$('#verName').value.trim()||'Manuskrip',at:new Date().toISOString(),content:structuredClone(p.content),outline:structuredClone(p.outline),checklist:structuredClone(p.checklist)});await saveProject();closeModal();renderProject('versions')}};$$('[data-openver]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.openver),v=p.goals.versions[i];modal(`<h2>${esc(v.name)}</h2><p class="muted">${new Date(v.at).toLocaleString('ms-MY')}</p><div style="max-height:55dvh;overflow:auto;border:1px solid var(--line);border-radius:12px;padding:14px">${Object.entries(v.content||{}).map(([k,x])=>`<h3>${esc(k)}</h3><div>${x||'<em>Empty</em>'}</div>`).join('')}</div><div class="actions"><button class="btn" onclick="closeModal()">Tutup</button><button class="btn primary" id="restoreVersion">Restore Versi Ini</button></div>`);$('#restoreVersion').onclick=async()=>{p.content=structuredClone(v.content);p.outline=structuredClone(v.outline);p.checklist=structuredClone(v.checklist);await saveProject();closeModal();toast('Versi manuskrip dipulihkan.');renderProject('versions')}});$$('[data-delver]').forEach(b=>b.onclick=async()=>{p.goals.versions.splice(Number(b.dataset.delver),1);await saveProject();renderProject('versions')})}
if(tab==='export'){$('#exportTxt').onclick=()=>downloadBlob(slug(p.title)+'.txt',new Blob([manuscriptText(p)],{type:'text/plain'}));$('#printPdf').onclick=()=>printManuscript(p);$('#exportDocx').onclick=async()=>{const file=await makeDocx(p);downloadBlob(slug(p.title)+'.docx',file)};$('#shareCloud').onclick=async()=>{const file=await makeDocx(p),f=new File([file],slug(p.title)+'.docx',{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});if(navigator.canShare?.({files:[f]})){await navigator.share({title:p.title,text:'Naskhah Studio manuscript',files:[f]})}else{downloadBlob(f.name,file);toast('Share sheet tidak disokong. Fail telah dimuat turun.')}}}}
function bindWriter(p){let sec=state.activeSection,ed=$('#editor'),timer;const sync=()=>{p.content[sec]=ed.innerHTML;$('#sectionWords').textContent=countWords(ed.innerHTML);$('#totalWords').textContent=projectWords(p);$('#readingTime').textContent=Math.max(1,Math.ceil(projectWords(p)/220))+' min'};const manual=async()=>{sync();$('#manualSave').disabled=true;$('#manualSave').textContent='Menyimpan...';try{await saveProject();$('#saveState').textContent='Disimpan secara manual';$('#manualSave').textContent='✓ DISIMPAN';setTimeout(()=>{$('#manualSave').textContent='💾 SIMPAN / SAVE';$('#manualSave').disabled=false},1000);toast(sec+' disimpan.')}catch(e){$('#manualSave').disabled=false;$('#manualSave').textContent='💾 SIMPAN / SAVE';toast(e.message,true)}};$$('[data-section]').forEach(b=>b.onclick=async()=>{sync();clearTimeout(timer);try{await saveProject()}catch{}state.activeSection=b.dataset.section;renderProject('writing')});ed.oninput=()=>{sync();$('#saveState').textContent='Menyimpan...';clearTimeout(timer);timer=setTimeout(async()=>{try{await saveProject();$('#saveState').textContent='Tersimpan di cloud'}catch(e){$('#saveState').textContent='Gagal autosave'}},700)};$('#manualSave').onclick=manual;$('#undoBtn').onclick=()=>{ed.focus();document.execCommand('undo')};$('#redoBtn').onclick=()=>{ed.focus();document.execCommand('redo')};$('#focusToggle').onclick=()=>{state.focus=!state.focus;$('#writerLayout').classList.toggle('focus-mode',state.focus);$('#focusToggle').textContent=state.focus?'Exit Focus':'Focus Writing'};$('#toolsToggle').onclick=()=>{state.toolsHidden=!state.toolsHidden;$('#writerLayout').classList.toggle('tools-hidden',state.toolsHidden);$('#toolsToggle').textContent=state.toolsHidden?'Show Tools':'Hide Tools'};$$('[data-cmd]').forEach(b=>b.onclick=()=>{ed.focus();document.execCommand(b.dataset.cmd)});$('#fontFamily').onchange=e=>{ed.focus();document.execCommand('fontName',false,e.target.value)};$('#fontSize').onchange=e=>{ed.focus();document.execCommand('fontSize',false,e.target.value)};$('#lineHeight').onchange=e=>{ed.style.lineHeight=e.target.value};$('#insertTable').onclick=()=>openTableDialog(ed);$('#insertImage').onclick=()=>$('#imageFile').click();$('#imageFile').onchange=()=>uploadImage(p,ed,$('#imageFile').files?.[0]);ed.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();manual()}};hydrateImages(ed)}
function openTableDialog(ed){modal(`<h2>Insert Table</h2><div class="grid2"><label>Rows<input id="tblRows" type="number" min="1" max="30" value="3"></label><label>Columns<input id="tblCols" type="number" min="1" max="12" value="3"></label></div><label>Caption<input id="tblCaption" placeholder="Table 1: ..."></label><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="tblInsert">Insert</button></div>`);$('#tblInsert').onclick=()=>{const rows=Math.min(30,Math.max(1,Number($('#tblRows').value||3))),cols=Math.min(12,Math.max(1,Number($('#tblCols').value||3))),cap=$('#tblCaption').value.trim();let html=cap?`<p><strong>${esc(cap)}</strong></p>`:'';html+='<table class="manuscript-table"><tbody>';for(let r=0;r<rows;r++){html+='<tr>';for(let c=0;c<cols;c++)html+=r===0?'<th>Heading</th>':'<td>Data</td>';html+='</tr>'}html+='</tbody></table><p><br></p>';ed.focus();document.execCommand('insertHTML',false,html);ed.dispatchEvent(new Event('input',{bubbles:true}));closeModal()}}
async function uploadImage(p,ed,file){if(!file)return;if(file.size>10*1024*1024)return toast('Maksimum gambar 10MB.',true);try{const u=(await sb.auth.getUser()).data.user,path=`${u.id}/${p.id}/${crypto.randomUUID()}.${(file.name.split('.').pop()||'png').toLowerCase()}`;const {error}=await sb.storage.from('naskhah-media').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;const {data}=await sb.storage.from('naskhah-media').createSignedUrl(path,3600);const cap=prompt('Caption gambar/graf (optional):')||'';ed.focus();document.execCommand('insertHTML',false,`<figure class="manuscript-figure"><img data-naskhah-path="${esc(path)}" src="${esc(data.signedUrl)}" alt="${esc(cap||file.name)}">${cap?`<figcaption>${esc(cap)}</figcaption>`:''}</figure><p><br></p>`);ed.dispatchEvent(new Event('input',{bubbles:true}));toast('Gambar dimasukkan.')}catch(e){toast(e.message||'Upload gagal.',true)}}
async function hydrateImages(ed){for(const img of ed.querySelectorAll('img[data-naskhah-path]')){const {data}=await sb.storage.from('naskhah-media').createSignedUrl(img.dataset.naskhahPath,3600);if(data?.signedUrl)img.src=data.signedUrl}}
function manuscriptText(p){return Object.entries(p.content).map(([k,v])=>k.toUpperCase()+'\n\n'+stripHtml(v)).join('\n\n\n')}
function slug(s){return String(s||'manuskrip').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'manuskrip'}
function downloadBlob(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function printManuscript(p){const w=open('','_blank');w.document.write(`<html><head><title>${esc(p.title)}</title><style>body{font-family:Times New Roman,serif;max-width:800px;margin:40px auto;line-height:1.6}h1{text-align:center}h2{margin-top:32px}img{max-width:100%}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:6px}</style></head><body><h1>${esc(p.title)}</h1>${Object.entries(p.content).map(([k,v])=>`<h2>${esc(k)}</h2>${v}`).join('')}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),300)}
async function makeDocx(p){const zip=new JSZip(),xmlEsc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));const paras=[];paras.push(`<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val="32"/></w:rPr><w:t>${xmlEsc(p.title)}</w:t></w:r></w:p>`);for(const [k,v] of Object.entries(p.content)){paras.push(`<w:p><w:r><w:rPr><w:b/><w:sz w:val="28"/></w:rPr><w:t>${xmlEsc(k)}</w:t></w:r></w:p>`);for(const line of stripHtml(v).split(/\n+/).filter(Boolean))paras.push(`<w:p><w:r><w:rPr><w:sz w:val="24"/></w:rPr><w:t xml:space="preserve">${xmlEsc(line)}</w:t></w:r></w:p>`)}zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');zip.folder('_rels').file('.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');zip.folder('word').file('document.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paras.join('')}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`);return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
async function renderProfile(){nav('profile');const p=state.profile,registered=p.created_at?new Date(p.created_at).toLocaleString('ms-MY'):'—',expiry=p.subscription_expires_at?new Date(p.subscription_expires_at).toLocaleDateString('ms-MY'):'—';$('#main').innerHTML=`<div class="page-head"><div><h1>Profile & Subscription</h1><p>Urus profil, email, password dan rekod langganan.</p></div></div><div class="grid2"><div class="card"><h2>Maklumat Profil</h2><label>Nama<input id="pfName" value="${esc(p.display_name||'')}"></label><label>Username<input value="${esc(p.username||'')}" disabled></label><label>Email<input id="pfEmail" type="email" value="${esc(p.email||'')}"></label><button class="btn primary" id="saveProfile" style="margin-top:14px">Simpan Perubahan</button></div><div class="card"><h2>Rekod Akaun & Langganan</h2><div class="profile-row"><span>Tarikh mula daftar</span><b>${registered}</b></div><div class="profile-row"><span>Plan semasa</span><b>${esc((p.plan||'free').toUpperCase())}</b></div><div class="profile-row"><span>Status langganan</span><b>${esc(p.subscription_status||'trial')}</b></div><div class="profile-row"><span>Tarikh tamat</span><b>${expiry}</b></div><div class="profile-row"><span>Status akaun</span><b>${esc(p.status||'active')}</b></div></div></div><div class="card" style="max-width:620px"><h2>Tukar Password</h2><label>Password Baharu<input id="newPass" type="password" minlength="6"></label><button class="btn primary" id="changePass" style="margin-top:14px">Tukar Password</button></div>`;$('#saveProfile').onclick=async()=>{const name=$('#pfName').value.trim(),email=$('#pfEmail').value.trim();if(email&&!/^\S+@\S+\.\S+$/.test(email))return toast('Format email tidak sah.',true);try{if(email&&email.toLowerCase()!==(p.email||'').toLowerCase()){const {error}=await sb.auth.updateUser({email});if(error)throw error}const {error}=await sb.from('nv1_profiles').update({display_name:name,email:email||null,updated_at:new Date().toISOString()}).eq('id',p.id);if(error)throw error;p.display_name=name;p.email=email||null;toast('Profil disimpan.')}catch(e){toast(e.message,true)}};$('#changePass').onclick=async()=>{const pw=$('#newPass').value;if(pw.length<6)return toast('Minimum 6 aksara.',true);const {error}=await sb.auth.updateUser({password:pw});if(error)return toast(error.message,true);$('#newPass').value='';toast('Password berjaya ditukar.')}}
async function renderAdmin(){if(state.profile?.role!=='admin')return renderDashboard();nav('admin');const [{data:users,error:uErr},{data:meta,error:mErr}]=await Promise.all([sb.from('nv1_profiles').select('id,username,display_name,email,role,status,plan,subscription_status,subscription_expires_at,created_at,last_seen_at').order('created_at',{ascending:false}),sb.from('nv1_project_metadata').select('*').order('created_at',{ascending:false})]);if(uErr)return toast(uErr.message,true);const us=users||[],ps=mErr?[]:(meta||[]);$('#main').innerHTML=`<div class="page-head"><div><h1>Admin Panel</h1><p>Urus akaun dan langganan. Kandungan manuskrip pengguna tidak dipaparkan.</p></div><button class="btn primary" id="addUser">+ Add User</button></div><div class="stats"><div class="stat"><b>${us.length}</b><span>Registered Users</span></div><div class="stat sections"><b>${us.filter(x=>x.status==='active').length}</b><span>Active Users</span></div><div class="stat words"><b>${ps.length}</b><span>Projects</span></div><div class="stat progress-card"><b>${us.filter(x=>['pro','premium','business'].includes((x.plan||'').toLowerCase())).length}</b><span>Paid Plans</span></div></div><div class="card"><h2>User Management</h2><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Registered</th><th>Plan</th><th>Subscription</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody>${us.map(u=>`<tr><td><b>${esc(u.display_name||u.username)}</b><br><small>@${esc(u.username)} · ${esc(u.role)}</small></td><td>${esc(u.email||'—')}</td><td>${u.created_at?new Date(u.created_at).toLocaleDateString('ms-MY'):'—'}</td><td>${esc((u.plan||'free').toUpperCase())}</td><td>${esc(u.subscription_status||'trial')}</td><td>${u.subscription_expires_at?new Date(u.subscription_expires_at).toLocaleDateString('ms-MY'):'—'}</td><td>${esc(u.status||'active')}</td><td><button class="btn small edit-user" data-id="${u.id}">Edit</button>${u.role!=='admin'&&u.status!=='active'?` <button class="btn small danger delete-user" data-id="${u.id}">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Project Metadata</h2><div class="table-wrap"><table><thead><tr><th>Project</th><th>Type</th><th>User</th><th>Created</th><th>Status</th></tr></thead><tbody>${ps.map(x=>`<tr><td>${esc(x.title||'')}</td><td>${esc(x.project_type||'')}</td><td>${esc(us.find(u=>u.id===x.user_id)?.username||'—')}</td><td>${x.created_at?new Date(x.created_at).toLocaleDateString('ms-MY'):'—'}</td><td>${esc(x.status||'')}</td></tr>`).join('')||'<tr><td colspan="5">Tiada metadata.</td></tr>'}</tbody></table></div></div>`;$('#addUser').onclick=adminCreateDialog;$$('.edit-user').forEach(b=>b.onclick=()=>adminEditDialog(us.find(u=>u.id===b.dataset.id)));$$('.delete-user').forEach(b=>b.onclick=()=>adminDeleteDialog(us.find(u=>u.id===b.dataset.id)))}
function adminCreateDialog(){modal(`<h2>Add User</h2><div class="grid2"><label>Nama<input id="auName"></label><label>Username<input id="auUser"></label></div><label>Email<input id="auEmail" type="email"></label><div class="grid2"><label>Password sementara<input id="auPass" type="password" value="user123"></label><label>Plan<select id="auPlan"><option>free</option><option>pro</option><option>premium</option><option>business</option></select></label></div><div class="grid2"><label>Status Langganan<select id="auSub"><option>trial</option><option>active</option></select></label><label>Tarikh Tamat<input id="auExpiry" type="date"></label></div><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="createUser">Cipta User</button></div>`);$('#createUser').onclick=async()=>{try{await authCall({action:'admin_create_user',username:$('#auUser').value.trim().toLowerCase(),password:$('#auPass').value,display_name:$('#auName').value.trim(),email:$('#auEmail').value.trim(),plan:$('#auPlan').value,subscription_status:$('#auSub').value,subscription_expires_at:$('#auExpiry').value?new Date($('#auExpiry').value+'T23:59:59').toISOString():null},true);closeModal();toast('User berjaya dicipta.');renderAdmin()}catch(e){toast(e.message,true)}}}
function adminEditDialog(u){const exp=u.subscription_expires_at?new Date(u.subscription_expires_at).toISOString().slice(0,10):'';modal(`<h2>Edit User</h2><div class="grid2"><label>Nama<input id="euName" value="${esc(u.display_name||'')}"></label><label>Username<input value="${esc(u.username||'')}" disabled></label></div><label>Email<input id="euEmail" type="email" value="${esc(u.email||'')}"></label><div class="grid2"><label>Plan<select id="euPlan"><option>free</option><option>pro</option><option>premium</option><option>business</option></select></label><label>Subscription<select id="euSub"><option>trial</option><option>active</option><option>past_due</option><option>cancelled</option><option>expired</option></select></label></div><div class="grid2"><label>Expiry<input id="euExpiry" type="date" value="${exp}"></label><label>Status<select id="euStatus"><option>active</option><option>suspended</option></select></label></div><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="saveUser">Simpan</button></div>`);$('#euPlan').value=u.plan||'free';$('#euSub').value=u.subscription_status||'trial';$('#euStatus').value=u.status||'active';$('#saveUser').onclick=async()=>{const {error}=await sb.from('nv1_profiles').update({display_name:$('#euName').value.trim(),email:$('#euEmail').value.trim()||null,plan:$('#euPlan').value,subscription_status:$('#euSub').value,subscription_expires_at:$('#euExpiry').value?new Date($('#euExpiry').value+'T23:59:59').toISOString():null,status:$('#euStatus').value,updated_at:new Date().toISOString()}).eq('id',u.id);if(error)return toast(error.message,true);closeModal();toast('User dikemas kini.');renderAdmin()}}
function adminDeleteDialog(u){modal(`<h2>Delete User</h2><p>Akaun <b>${esc(u.username)}</b> akan dipadam. Fungsi ini hanya dipaparkan untuk user yang tidak aktif/suspended.</p><label>Taip DELETE<input id="delConfirm"></label><div class="actions"><button class="btn" onclick="closeModal()">Batal</button><button class="btn danger" id="confirmDelete">Delete User</button></div>`);$('#confirmDelete').onclick=async()=>{if($('#delConfirm').value!=='DELETE')return toast('Taip DELETE untuk sahkan.',true);try{await authCall({action:'admin_delete_user',user_id:u.id},true);closeModal();toast('User dipadam.');renderAdmin()}catch(e){toast(e.message,true)}}}
function bindGlobal(){document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){const v=n.dataset.nav;if(v==='dashboard')renderDashboard();if(v==='projects')renderProjects();if(v==='profile')renderProfile();if(v==='admin')renderAdmin()}});$('#mobileNavToggle').onclick=()=>toggleNav();$('#mobileShade').onclick=()=>toggleNav(false);$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#logout').onclick=async()=>{await sb.auth.signOut();state={session:null,profile:null,projects:[],current:null,currentTab:'overview',activeSection:null,focus:false,toolsHidden:false};showPublic('login')}}
function bindAuth(){$('#goAdmin').onclick=()=>showPublic('admin');$$('.toLogin').forEach(x=>x.onclick=()=>showPublic('login'));$('#forgotLink').onclick=()=>showPublic('forgot');$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const j=await authCall({action:'login',identifier:$('#loginUser').value.trim(),password:$('#loginPass').value});await setSession(j.access_token,j.refresh_token);if(state.profile?.status==='suspended')throw new Error('Akaun digantung. Hubungi admin.');await enterApp()}catch(err){toast(err.message,true)}};$('#adminForm').onsubmit=async e=>{e.preventDefault();try{const j=await authCall({action:'login',identifier:$('#adminUser').value.trim(),password:$('#adminPass').value});await setSession(j.access_token,j.refresh_token);if(state.profile?.role!=='admin'){await sb.auth.signOut();throw new Error('Akaun ini bukan admin.')}await enterApp()}catch(err){toast(err.message,true)}};$('#forgotForm').onsubmit=async e=>{e.preventDefault();try{await authCall({action:'forgot',identifier:$('#forgotUser').value.trim(),redirect_to:location.origin+location.pathname});toast('Jika email recovery wujud, reset link telah dihantar.');showPublic('login')}catch(err){toast(err.message,true)}};$('#resetForm').onsubmit=async e=>{e.preventDefault();const a=$('#resetPass').value,b=$('#resetPass2').value;if(a!==b)return toast('Password tidak sama.',true);const {error}=await sb.auth.updateUser({password:a});if(error)return toast(error.message,true);toast('Password berjaya ditukar.');showPublic('login')}}
async function boot(){bindGlobal();bindAuth();const {data:{session}}=await sb.auth.getSession();if(session){try{state.session=session;await loadProfile();if(state.profile?.status==='active')return enterApp()}catch{}await sb.auth.signOut()}showPublic('login')}
document.addEventListener('DOMContentLoaded',boot);